let data=[],peaks=[],sortKey='year',sortDirection=-1,page=1;const pageSize=100,$=s=>document.querySelector(s),fmt=HimalayasCommon.fmt,esc=HimalayasCommon.esc;
function params(){return new URLSearchParams(location.search)}
function updateUrl(){const p=new URLSearchParams(),existing=params(),q=$('#search').value.trim(),peak=$('#peak').value,year=$('#year').value,result=$('#result').value,deaths=$('#deaths').value;if(q)p.set('q',q);if(peak!=='all')p.set('peak',peak);if(year!=='all')p.set('year',year);if(result!=='all')p.set('result',result);if(deaths!=='all')p.set('deaths',deaths);if(existing.get('decade'))p.set('decade',existing.get('decade'));if(sortKey!=='year'||sortDirection!==-1){p.set('sort',sortKey);p.set('dir',sortDirection>0?'asc':'desc')}if(page>1)p.set('page',page);history.replaceState(null,'',location.pathname+(p.toString()?'?'+p:''))}
function value(row,key){return key==='outcome'?row.sourceLabel:key==='id'?row.id:key==='year'?row.year:row[key]}
function compare(a,b){const av=value(a,sortKey),bv=value(b,sortKey);if(av==null&&bv==null)return a.id.localeCompare(b.id);if(av==null)return 1;if(bv==null)return -1;const n=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv));return n||a.id.localeCompare(b.id)}
function activeRows(){const q=$('#search').value.trim().toLowerCase();return data.filter(x=>(!q||x.searchKey.includes(q))&&($('#peak').value==='all'||x.peakId===$('#peak').value)&&($('#year').value==='all'||String(x.year)===$('#year').value)&&($('#result').value==='all'||($('#result').value==='summit'?x.hasRecordedSummit:$('#result').value==='undisputed'?x.hasUndisputedSummit:$('#result').value==='fail'?x.sourceResult==='fail':!x.hasRecordedSummit&&x.sourceResult!=='fail'))&&($('#deaths').value==='all'||($('#deaths').value==='yes'?Number(x.deaths)>0:Number(x.deaths)===0))).sort((a,b)=>compare(a,b)*sortDirection)}
function chip(label,clear){return '<button class="chip" data-clear="'+clear+'">'+esc(label)+' ×</button>'}
function render(){const rows=activeRows(),totalPages=Math.max(1,Math.ceil(rows.length/pageSize));if(page>totalPages)page=totalPages;const visible=rows.slice((page-1)*pageSize,page*pageSize);$('#result-note').textContent=rows.length?('Showing '+fmt((page-1)*pageSize+1)+'–'+fmt(Math.min(page*pageSize,rows.length))+' of '+fmt(rows.length)+' expeditions'): '0 expeditions';const chips=[];if($('#peak').value!=='all')chips.push(chip('Peak: '+$('#peak').selectedOptions[0].textContent,'peak'));if($('#year').value!=='all')chips.push(chip('Year: '+$('#year').value,'year'));if(params().get('decade'))chips.push(chip('Decade: '+params().get('decade')+'s','decade'));if($('#result').value!=='all')chips.push(chip($('#result').selectedOptions[0].textContent,'result'));if($('#deaths').value!=='all')chips.push(chip($('#deaths').selectedOptions[0].textContent,'deaths'));$('#chips').innerHTML=chips.join('');$('#rows').innerHTML=visible.length?visible.map(x=>'<tr><td><a href="expedition.html?id='+encodeURIComponent(x.id)+'">'+esc(x.id)+'</a><span class="sub">'+esc(x.leaderName||(x.leaderKind==='role'?x.leaderOrRole:'Leader not recorded'))+'</span></td><td><a href="peak.html?peak='+encodeURIComponent(x.peakId)+'">'+esc(x.mountain)+'</a><span class="sub">'+x.year+' · '+esc(HimalayasCommon.seasonLabel(x.season))+'</span></td><td>'+fmt(x.participants)+'<span class="sub">'+fmt(x.teamMembers)+' members · '+fmt(x.hiredStaff)+' hired</span></td><td>'+fmt(x.memberSummiters)+'<span class="sub">'+fmt(x.summitHired)+' hired</span></td><td>'+fmt(x.deaths)+'<span class="sub">'+fmt(x.memberDeaths)+' member · '+fmt(x.hiredDeaths)+' hired</span></td><td><span class="pill '+(x.hasRecordedSummit?'summit':x.sourceResult==='fail'?'tragedy':'')+'">'+esc(x.sourceLabel||x.sourceResult||'Outcome not recorded')+'</span></td></tr>').join(''):'<tr><td colspan="6" class="empty">No expeditions match those filters.</td></tr>';$('#pager').innerHTML=totalPages>1?'<button '+(page===1?'disabled':'')+' data-page="prev">Previous</button><span>Page '+page+' of '+totalPages+'</span><button '+(page===totalPages?'disabled':'')+' data-page="next">Next</button>':'';document.querySelectorAll('[data-sort]').forEach(button=>button.setAttribute('aria-sort',button.dataset.sort===sortKey?(sortDirection>0?'ascending':'descending'):'none'))}
function clearFilter(key){if(key==='decade'){const p=params();p.delete('decade');history.replaceState(null,'',location.pathname+(p.toString()?'?'+p:''));return location.reload()}$('#'+key).value='all';page=1;updateUrl();render()}
function loadState(){const p=params(),rawPeak=p.get('peak'),matchedPeak=peaks.find(x=>x.peakId===rawPeak||x.name===rawPeak);$('#search').value=p.get('q')||'';$('#peak').value=matchedPeak?matchedPeak.peakId:'all';$('#year').value=p.get('year')||'all';$('#result').value=p.get('result')||'all';$('#deaths').value=p.get('deaths')||'all';sortKey=p.get('sort')||'year';sortDirection=p.get('dir')==='asc'?1:-1;page=Math.max(1,Number(p.get('page')||1));const rawDecade=p.get('decade'),decade=rawDecade===null?null:Number(rawDecade);if(Number.isFinite(decade))data=data.filter(x=>Math.floor(x.year/10)*10===decade);render()}
document.querySelectorAll('[data-sort]').forEach(button=>{const activate=()=>{if(sortKey===button.dataset.sort)sortDirection*=-1;else{sortKey=button.dataset.sort;sortDirection=sortKey==='year'?-1:1}page=1;updateUrl();render()};button.addEventListener('click',activate);button.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}})});['search','peak','year','result','deaths'].forEach(id=>$('#'+id).addEventListener('input',()=>{page=1;updateUrl();render()}));$('#chips').addEventListener('click',e=>{const button=e.target.closest('[data-clear]');if(button)clearFilter(button.dataset.clear)});$('#pager').addEventListener('click',e=>{const button=e.target.closest('[data-page]');if(!button)return;page+=button.dataset.page==='next'?1:-1;updateUrl();render()});Promise.all([fetch('expeditions.json'),fetch('peaks.json')]).then(async rs=>{if(rs.some(r=>!r.ok))throw Error('Required expedition data files are missing');return Promise.all(rs.map(r=>r.json()))}).then(([rows,peakRows])=>{data=rows.map(x=>({...x,searchKey:[x.mountain,x.leaderName,x.leaderOrRole,x.route,x.id,x.sourceId].filter(Boolean).join(' ').toLowerCase()}));peaks=peakRows;peaks.slice().sort((a,b)=>a.name.localeCompare(b.name)).forEach(x=>{const o=document.createElement('option');o.value=x.peakId;o.textContent=x.name;$('#peak').appendChild(o)});[...new Set(data.map(x=>x.year).filter(Number.isFinite))].sort((a,b)=>b-a).forEach(y=>{const o=document.createElement('option');o.value=y;o.textContent=y;$('#year').appendChild(o)});loadState()}).catch(error=>{$('#result-note').textContent='Data unavailable';$('#rows').innerHTML='<tr><td colspan="6" class="empty"><strong>'+esc(error.message)+'</strong><br>Run scripts/build_data.py, dbt build, and scripts/export_site_data.py, then reload this page.</td></tr>'});
